-- Only in isolated synthetic environment. No production activation instruction.
SET ROLE mass_core_owner;
SELECT core_test.expect_error($q$UPDATE mass_activation.features SET enabled=true WHERE feature='attendance_entry'$q$,'23514','explicit non-null approval reference required');
UPDATE mass_activation.features SET enabled=true,approval_reference='synthetic isolated entry approval' WHERE feature IN ('attendance_entry','assessment_entry','visit_entry','reviewed_reads');
SELECT core_test.expect_error($q$UPDATE mass_activation.features SET enabled=true,approval_reference='synthetic' WHERE feature='transfers'$q$,'23514','transfer cannot be activated by a flag');
SELECT core_test.expect_error($q$UPDATE mass_activation.features SET enabled=true,approval_reference='synthetic' WHERE feature='attendance_corrections'$q$,'23514','historical overwrite cannot be activated by a flag');
RESET ROLE;
SET ROLE mass_core_admin;
INSERT INTO mass_core.assessment_periods(id,academic_year_id,quarter) VALUES('90000000-0000-4000-8000-000000000007','90000000-0000-4000-8000-000000000003',2);
INSERT INTO mass_core.assessment_definitions(id,period_id) VALUES('90000000-0000-4000-8000-000000000008','90000000-0000-4000-8000-000000000007');
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000001"}',false);
SELECT core_test.assert_true(mass_core.operation_enabled('attendance_entry'),'explicit scoped insert feature enabled');
SELECT mass_api.record_attendance(enrolment_id,'2026-04-06','P',0) FROM upgrade_test.student;
SELECT core_test.expect_error(format('SELECT mass_api.record_attendance(%L,''2026-04-07'',''P'',0)',core_test.id('foreign')),'42501','enabled flag cannot override foreign-centre, expired or future scopes');
SELECT core_test.expect_error(format('SELECT mass_api.record_assessment(%L,''90000000-0000-4000-8000-000000000008'',NULL,26,0)',enrolment_id),'23514','assessment entry retains maximum25 validation') FROM upgrade_test.student;
SELECT mass_api.record_assessment(enrolment_id,'90000000-0000-4000-8000-000000000008',NULL,25,0) FROM upgrade_test.student;
SELECT core_test.assert_true((SELECT assessed_on IS NULL AND score=25 FROM mass_core.assessment_results WHERE definition_id='90000000-0000-4000-8000-000000000008'),'enabled new quarter result preserves unknown exact date');
SELECT core_test.expect_error('SELECT mass_api.record_visit(NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,NULL)','23514','enabled visit retains original input validation');
SELECT core_test.expect_error($q$SELECT mass_api.record_visit(gen_random_uuid(),gen_random_uuid(),'Morning','2026-04-07','Completed','Synthetic','',0,NULL)$q$,'42501','visit flag cannot invent an officer assignment or role');
SELECT core_test.expect_error(format($q$SELECT mass_api.record_attendance_batch(jsonb_build_array(jsonb_build_object('enrolment',%L,'date','2026-04-01','code','P','expected',0),jsonb_build_object('enrolment',%L,'date','2026-04-06','code','A','expected',1)))$q$,enrolment_id,enrolment_id),'42501','mixed insert/correction batch rolls back entirely') FROM upgrade_test.student;
SELECT core_test.assert_true((SELECT count(*)=0 FROM mass_core.attendance_records WHERE attendance_date='2026-04-01'),'failed mixed batch preserves unknown day');
SELECT core_test.expect_error(format('SELECT mass_api.record_attendance(%L,''2026-04-06'',''A'',1)',enrolment_id),'42501','existing attendance correction still denied') FROM upgrade_test.student;
SELECT core_test.expect_error(format('SELECT mass_api.record_attendance(%L,''2026-04-06'',''A'',0)',enrolment_id),'PT409','cannot disguise an overwrite as an insert') FROM upgrade_test.student;
SELECT core_test.expect_error(format('SELECT mass_api.record_assessment(%L,''90000000-0000-4000-8000-000000000005'',''2026-04-12'',10,1)',enrolment_id),'42501','existing assessment correction still denied') FROM upgrade_test.student;
SELECT core_test.assert_true((mass_api.reviewed_chart_metrics(ARRAY['90000000-0000-4000-8000-000000000002']::uuid[],'2026-04-30','2026-04-01','2026-05-01','90000000-0000-4000-8000-000000000003')->>'children')::int=1,'approved aggregate remains available after separate enable');
SELECT set_config('request.jwt.claims','{"sub":"91000000-0000-4000-8000-000000000001"}',false);
SELECT core_test.expect_error(format('SELECT mass_api.record_attendance(%L,''2026-04-07'',''P'',0)',enrolment_id),'42501','enabled flag does not override Leadership veto') FROM upgrade_test.student;
RESET ROLE;
SELECT core_test.assert_true((SELECT count(*)=4 FROM mass_activation.events),'activation changes auditable; rejected changes do not persist');
SET ROLE mass_core_owner;
UPDATE mass_activation.features SET enabled=false,approval_reference='synthetic disable' WHERE enabled;
RESET ROLE;
SET ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"90000000-0000-4000-8000-000000000001"}',false);
SELECT core_test.expect_error(format('SELECT mass_api.record_attendance(%L,''2026-04-07'',''P'',0)',enrolment_id),'42501','disabling blocks the next direct call') FROM upgrade_test.student;
RESET ROLE;
